// ServerInterface represents all server handlers.
type ServerInterface interface {
	// Check process health
	// (GET /healthz)
	GetHealth(w http.ResponseWriter, r *http.Request)
	// Check API readiness
	// (GET /readyz)
	GetReadiness(w http.ResponseWriter, r *http.Request)
	// Set or change the current user's contact email
	// (PUT /v1/auth/email)
	SetAuthEmail(w http.ResponseWriter, r *http.Request)
	// Verify a contact email with a token
	// (POST /v1/auth/email/verification)
	VerifyAuthEmail(w http.ResponseWriter, r *http.Request)
	// Resend the email verification message
	// (POST /v1/auth/email/verifications)
	CreateAuthEmailVerification(w http.ResponseWriter, r *http.Request)
	// Exchange a provider identity token for a session
	// (POST /v1/auth/oidc/sessions)
	CreateAuthOidcSession(w http.ResponseWriter, r *http.Request)
	// Set a new password with a reset token
	// (POST /v1/auth/password)
	SetAuthPassword(w http.ResponseWriter, r *http.Request)
	// Request a password reset link by email
	// (POST /v1/auth/password-resets)
	CreateAuthPasswordReset(w http.ResponseWriter, r *http.Request)
	// Delete the current authenticated session
	// (DELETE /v1/auth/session)
	DeleteAuthSession(w http.ResponseWriter, r *http.Request)
	// Get the current authenticated session
	// (GET /v1/auth/session)
	GetAuthSession(w http.ResponseWriter, r *http.Request)
	// Create an authenticated session
	// (POST /v1/auth/sessions)
	CreateAuthSession(w http.ResponseWriter, r *http.Request)
	// Create a user account
	// (POST /v1/auth/users)
	CreateAuthUser(w http.ResponseWriter, r *http.Request)
	// Permanently delete the authenticated user's account
	// (DELETE /v1/auth/users/me)
	DeleteAuthUser(w http.ResponseWriter, r *http.Request)
	// Get a public author profile
	// (GET /v1/authors/{author_id})
	GetAuthor(w http.ResponseWriter, r *http.Request, authorId string)
	// List an author's notes
	// (GET /v1/authors/{author_id}/notes)
	ListAuthorNotes(w http.ResponseWriter, r *http.Request, authorId string, params ListAuthorNotesParams)
	// List category catalog
	// (GET /v1/categories)
	ListCategories(w http.ResponseWriter, r *http.Request)
	// Reply to a top-level note comment
	// (POST /v1/comments/{comment_id}/replies)
	CreateCommentReply(w http.ResponseWriter, r *http.Request, commentId string)
	// Record product events
	// (POST /v1/events)
	CreateEvents(w http.ResponseWriter, r *http.Request)
	// Stage one private image upload
	// (POST /v1/media/image-uploads)
	PrepareImageUpload(w http.ResponseWriter, r *http.Request)
	// Serve an attached image
	// (GET /v1/media/images/{image_id})
	GetMediaImage(w http.ResponseWriter, r *http.Request, imageId openapi_types.UUID)
	// List recent notes
	// (GET /v1/notes)
	ListNotes(w http.ResponseWriter, r *http.Request, params ListNotesParams)
	// Create a note
	// (POST /v1/notes)
	CreateNote(w http.ResponseWriter, r *http.Request)
	// Delete a note
	// (DELETE /v1/notes/{note_id})
	DeleteNote(w http.ResponseWriter, r *http.Request, noteId string)
	// Get a note
	// (GET /v1/notes/{note_id})
	GetNote(w http.ResponseWriter, r *http.Request, noteId string)
	// Update a note
	// (PATCH /v1/notes/{note_id})
	UpdateNote(w http.ResponseWriter, r *http.Request, noteId string)
	// List note comments
	// (GET /v1/notes/{note_id}/comments)
	ListNoteComments(w http.ResponseWriter, r *http.Request, noteId string, params ListNoteCommentsParams)
	// Create a note comment
	// (POST /v1/notes/{note_id}/comments)
	CreateNoteComment(w http.ResponseWriter, r *http.Request, noteId string)
	// Delete a note comment
	// (DELETE /v1/notes/{note_id}/comments/{comment_id})
	DeleteNoteComment(w http.ResponseWriter, r *http.Request, noteId string, commentId string)
	// Remove a useful mark from a note
	// (DELETE /v1/notes/{note_id}/useful)
	UnmarkNoteUseful(w http.ResponseWriter, r *http.Request, noteId string)
	// Mark a note as useful
	// (PUT /v1/notes/{note_id}/useful)
	MarkNoteUseful(w http.ResponseWriter, r *http.Request, noteId string)
	// Create a report
	// (POST /v1/reports)
	CreateReport(w http.ResponseWriter, r *http.Request)
	// Search notes
	// (GET /v1/search/notes)
	SearchNotes(w http.ResponseWriter, r *http.Request, params SearchNotesParams)
}

